<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Propiedades de la cuota</title><style>
body{font:10px Arial,sans-serif;color:#343a40;margin:0}table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{padding:6px 4px;vertical-align:top}thead{display:table-header-group}tr{page-break-inside:avoid}th{background:#42494c;color:white;font-size:9px}tbody td{border-bottom:1px solid #ddd}tbody tr:nth-child(even){background:#f7f7f7}.cabecera{border-bottom:2px solid #a58828;margin-bottom:12px}.empresa{text-align:right;font-size:9px;line-height:1.4}.logo{width:145px}h1{font-size:19px;margin-bottom:5px}.nota{font-size:9px;color:#666}.totales{margin:12px 0;background:#f6f4ee}.totales b{display:block;font-size:14px;margin-top:5px}.importe{text-align:right;white-space:nowrap}.contacto{font-size:8px;color:#656f76;word-wrap:break-word}.estado{font-size:9px}.pendiente{color:#ae6226}.pagado{color:#337458}tfoot td{font-weight:bold;background:#f5f3ec}@page{size:letter portrait}
</style></head><body>
<table class="cabecera"><tr><td><img class="logo" src="{{ public_path(env('LOGOJPG')) }}" alt="Aeternus Funerales"></td><td class="empresa"><b>{{ \App\Exports\NombreEmpresaReportes::formatear($empresa['nombre_comercial'] ?? null) }}</b><br>{{ $empresa['razon_social'] ?? '' }}<br>{{ \App\Exports\DireccionReportes::formatear($empresa) }}<br>Tel. {{ $empresa['telefono'] ?? '' }}</td></tr></table>
<h1>{{ $cuota->descripcion }}</h1>
<p class="nota">Propiedades y saldos de la cuota · {{ $filtro }} · Consulta: {{ \Carbon\Carbon::now('America/Mazatlan')->locale('es')->translatedFormat('d/M/Y') }}</p>
<p class="nota">Estado de la cuota: {{ (int)$cuota->status === 1 ? 'Activa' : 'Cancelada · Consulta histórica' }}. Capital sin intereses.</p>
<table class="totales"><tr><td>Propiedades<b>{{ $filas->count() }}</b></td><td>Capital programado<b>$ {{ number_format($filas->sum('programado'),2) }} MXN</b></td><td>Capital cubierto<b>$ {{ number_format($filas->sum('cubierto'),2) }} MXN</b></td><td>Saldo pendiente<b>$ {{ number_format($filas->sum('pendiente'),2) }} MXN</b></td></tr></table>
<table><colgroup><col style="width:25%"><col style="width:30%"><col style="width:15%"><col style="width:15%"><col style="width:15%"></colgroup><thead><tr><th>Propiedad / venta</th><th>Titular y contacto</th><th>Programado</th><th>Cubierto</th><th>Pendiente</th></tr></thead><tbody>
@forelse($filas as $fila)
<tr><td><b>{{ $fila->ubicacion }}</b><div class="contacto">Venta {{ $fila->venta }}</div><div class="estado {{ $fila->pendiente > 0 ? 'pendiente' : 'pagado' }}">{{ $fila->pendiente > 0 ? 'Con adeudo' : 'Pagada' }}</div></td><td><b>{{ $fila->nombre ?: 'No disponible' }}</b><div class="contacto">{{ implode(' / ', array_filter([$fila->celular, $fila->telefono])) ?: 'Sin teléfono' }}<br>{{ $fila->email ?: 'Sin correo' }}</div></td><td class="importe">$ {{ number_format($fila->programado,2) }}</td><td class="importe">$ {{ number_format($fila->cubierto,2) }}</td><td class="importe">$ {{ number_format($fila->pendiente,2) }}</td></tr>
