</tbody><tfoot><tr><td colspan="2">Totales · MXN</td><td class="importe">$ {{ number_format($filas->sum('programado'),2) }}</td><td class="importe">$ {{ number_format($filas->sum('cubierto'),2) }}</td><td class="importe">$ {{ number_format($filas->sum('pendiente'),2) }}</td></tr></tfoot></table>
</body></html>
